INSERT INTO `news` VALUES (20, 't020', 'https://chinavolunteer.mca.gov.cn/', '2024-07-20', 0, 1, '生命教育：志愿者参与无偿献血公益活动', '<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">7月3日，青岛市首个&ldquo;暖心社保志愿服务站&rdquo;在青岛市社保中心市北分中心服务大厅启用。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=cd38ffc7697047b9bc35b5bd02cc5bae\" /></p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">青岛市委社会工作部、市直机关工委、共青团青岛市委、市新时代文明实践指导中心等单位相关领导莅临启用仪式现场，共同为服务站揭牌，并为&ldquo;青岛暖心社保志愿服务队&rdquo;授旗。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=25e01924371440999a1428419c2fdff6\" /></p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">作为社会保障领域公共服务的提供者，近年来，全市社保经办机构不断创新服务方式，拓宽服务渠道，推动社保经办方式向更加人性化、多样化、精细化转变，着力提升社保服务的温度、速度和力度。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=46977d84a824464193d3adbef6d6b138\" /></p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">为进一步创新社保服务模式，提升社保治理效能，青岛市社保中心探索将社保经办与志愿服务相融合，依托社保服务大厅打造&ldquo;暖心社保志愿服务站&rdquo;，汇聚政府机关、社保系统、合作银行、协同部门、爱心企业等志愿力量组建&ldquo;青岛暖心社保志愿服务队&rdquo;，开展社保服务、社会公益等多项志愿服务项目，培育社保志愿服务品牌，引导社会各界关注、支持和参与社保志愿服务，更好地在服务企业、服务群众、服务社会中贡献社保志愿力量。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=3a98801c9fbe48838125cf17ab4212f6\" /></p>', '标签');
