tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">为进一步创新社保服务模式，提升社保治理效能，青岛市社保中心探索将社保经办与志愿服务相融合，依托社保服务大厅打造&ldquo;暖心社保志愿服务站&rdquo;，汇聚政府机关、社保系统、合作银行、协同部门、爱心企业等志愿力量组建&ldquo;青岛暖心社保志愿服务队&rdquo;，开展社保服务、社会公益等多项志愿服务项目，培育社保志愿服务品牌，引导社会各界关注、支持和参与社保志愿服务，更好地在服务企业、服务群众、服务社会中贡献社保志愿力量。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=3a98801c9fbe48838125cf17ab4212f6\" /></p>', '助老助残志愿服务');
INSERT INTO `news` VALUES (28, 't001', NULL, '2024-06-30', 0, 0, '陕西省洛南县第三届新时代文明实践志愿服务项目大赛举行', '<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">文明，于一座城而言，既是最好的标签，也是最美的底色。初夏时分，漫步在县城各个角落，文明之风处处涌现......。&rdquo;</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">&ldquo;我们积极探索推行&lsquo;文艺化&rsquo;宣讲形式，把群众感兴趣、易接受的理论&lsquo;兴奋点&rsquo;融入文艺文化作品创作......&rdquo;。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px 0px 15px;\" title=\"1717060179821455.jpg\" src=\"https://xmupload.ceweekly.cn/1/2024/0530/1717060179821455.jpg\" alt=\"mmexport1717055373852.jpg\" /></p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">5月29日，洛南县举行第三届新时代文明实践志愿服务项目大赛，县委常委、宣传部部长郭民成出席活动并讲话，县委文明办、县新时代文明实践中心、团委、党校等部门负责同志，16个镇办党委副书记、宣传干部、部分文明实践站站长、文明单位代表参加活动。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px 0px 15px;\" title=\"1717060155907095.jpg\" src=\"https://xmupload.ceweekly.cn/1/2024/0530/1717060155907095.jpg\" alt=\"mmexport1717055379682.jpg\" /></p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">郭民成在讲话中强调，要充分发挥文明实践一体化、精准化、常态化工作机制作用，精准对接群众需求，扎实开展新时代文明实践工作。要将文明实践阵地向基层、向末梢延伸，把文明实践阵地打造成当地的文化地标、精神地标，使文明实践&ldquo;接地气&rdquo;，服务群众&ldquo;零距离&rdquo;。要坚持聘任一批、招募一批、表彰一批、培育一批，持续壮大志愿服务队伍。要紧紧围绕工作重点，创新方式方法，倾心打造叫得响、立得住、传得开的志愿服务项目，切实以项目引领文明实践工作高质量发展。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">据了解，本次项目大赛由中共洛南县委宣传部主办，县委文明办、县新时代文明实践中心承办，县融媒体中心、县职教中心协办，本次项目大赛前期共收到65个申报项目，最终12个项目进入决赛，决赛项目通过路演方式进行，由项目解说人通过PPT、短视频等方式进行现场展示，评委现场进行打分。经过激烈角逐，最终青年志愿服务队的&ldquo;创建卫生县城 践行生态文明&rdquo;项目荣获一等奖，古城镇柏庵村新时代文明实践站的&ldquo;保护古树名木 守护绿色瑰宝&rdquo;和洛源镇新时代文明实践所的&ldquo;文艺宣讲促乡村振兴&rdquo;项目荣获二等奖，景村镇兑山村新时代文明实践站的&ldquo;和睦邻里情 爱心沁乡村&rdquo;等3个项目荣获三等奖，城关街道罗坡村新时代文明实践站的&ldquo;桑榆之声传党恩&rdquo;等6个项目获得优秀奖。</p>', '社区志愿服务');
INSERT INTO `news` VALUES (35, 't001', NULL, '2024-07-01', 0, 0, '湖南发布一批文旅志愿服务先进典型', '<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">4月18日，湖南省文旅志愿服务先进典型发布仪式在湖南省少年儿童图书馆举行。现场，湖南省文化和旅游厅发布了包括&ldquo;最美文旅志愿者&rdquo;&ldquo;最美文旅志愿服务组织工作者&rdquo;&ldquo;最佳文旅志愿服务组织&rdquo;&ldquo;最佳文旅志愿服务项目&rdquo;&ldquo;最美文旅志愿服务社区&rdquo;在内的96个先进典型，并为新成立的11支文旅志愿服务高校支队和1支厅机关支队授旗。</p>\n<figure style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://img2.voc.com.cn/2024/04/18/de45543e0ef23905d24dde4b550ef4dcfac752181713443618.png\" /></figure>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: center; line-height: 40px !important;\">活动现场</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">近年来，湖南省文化和旅游厅以&ldquo;雷锋家乡学雷锋&rdquo;为统领，以&ldquo;到群众最需要的地方去&rdquo;为品牌，常态化、制度化纵深推进全省文旅志愿服务工作，在队伍建设、品牌打造、服务效能等方面成效明显。目前，我省省直、市州、高校、社会团体共有42个文旅志愿服务支队、4031个分队，注册文旅志愿者38.9万名；&ldquo;播撒艺术的种子&rdquo;&ldquo;旅游医生&rdquo;&ldquo;湖南农民工春晚&rdquo;等20余项全省文旅志愿服务品牌活动的影响力显著。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">湖南省文化和旅游厅党组成员、副厅长尚斌表示，下一步将继续加强志愿服务的培训和指导，提升志愿者的专业素养和服务能力，在三湘大地上深情书写新时代&ldquo;雷锋家乡学雷锋&rdquo;动人新篇章。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">附：</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><strong style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000;\">2023年度湖南省文旅志愿服务先进典型名单</strong></p>\n<figure style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://img2.voc.com.cn/2024/04/18/5fec898690f6dc120211d98502ba9b05163d57771713443628.png\" /></figure>\n<figure style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://img2.voc.com.cn/2024/04/18/99b3162b7b5d28836d5996a31a081535571f5ce91713443636.png\" /></figure>\n<figure style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://img2.voc.com.cn/2024/04/18/bc9cd85588e45b41c4a926439833b4fbfc1769641713443645.png\" /></figure>\n<figure style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://img2.voc.com.cn/2024/04/18/64839178fbe11086071f81d06e4745ee0530c3531713443666.png\" /></figure>\n<figure style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://img2.voc.com.cn/2024/04/18/1836b4c6b5f4d75329f3333399c4960c5bbd9f5b1713443694.png\" /></figure>', '助老助残志愿服务');
INSERT INTO `news` VALUES (36, 't001', NULL, '2024-08-01', 0, 1, '中华红丝带基金举行2023年志愿者培训活动', '<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">中新网北京12月18日电 由中华红丝带基金、北京红丝带之家和中国医药卫生文化协会高校医院分会共同主办的&ldquo;红丝带连接你和我&mdash;&mdash;中华红丝带基金志愿者培训&rdquo;活动16日在对外经济贸易大学举办。</span></p>\n<div class=\"_3hMwG _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\">\n<div class=\"_1NCGf\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=feef9e52e9d24e9a95f3d23a3959f7bf\" /></div>\n</div>\n<div class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: center;\">图为与会嘉宾分享防艾故事。主办方供图</div>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">活动中，中国疾控中心艾滋病防治首席专家韩孟杰为志愿者讲授了防艾抗艾知识，北京信息科技大学副教授、北京志愿服务发展研究会副秘书长田丽娜介绍了志愿服务的相关知识。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">中华红丝带基金常务副理事长谷彦芬、中国医药卫生文化协会高校医院分会会长杨大来、对外经济贸易大学校医院院长刘静、北京市红十字风之彩志愿服务大队队长刘慧娟、北京大学公共卫生学院学生杨硕等嘉宾分享了参与和组织志愿活动的经验与故事。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">2020年以来，&ldquo;聚力防疫抗艾，共担健康责任&rdquo;校园情景剧公益展播系列活动在青年群体和社会公众中产生强烈反响，中华红丝带基金启动了以线上为主、面授为辅的志愿者培训活动，截至目前已吸引近10万名热心人士和志愿者参与。</span></p>', '助老助残志愿服务');
INSERT INTO `news` VALUES (38, 't001', NULL, '2024-08-01', 0, 1, '温州轨道S1线反诈宣传工作站揭牌启用 700余名社会志愿者投身反诈工作', '<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=96efc29a89c140c4b935d43a2dcf718e\" /></p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">为弘扬&ldquo;奉献、博爱、互助、进步&rdquo;的志愿者精神，释放志愿服务在反诈工作中的重要作用，6月19日上午，浙江省温州市公安局城市公共交通分局、市反诈中心联合浙江幸福轨道公司、龙霞退役军人守护站、北京恒安卫士保安服务公司、浙江工贸、浙江安防、温州大学、温州医科大学等一众高校，在轻轨S1线惠民路站的站厅内举行志愿者服务队授旗暨轨道S1线反诈工作站揭牌活动，着力打造&ldquo;公安蓝+志愿红&rdquo;的城市公共交通志愿服务新模式，将广大志愿者投身于反诈预防宣传工作之中。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">城市公共交通志愿者服务队前身为&ldquo;龙侠义警&rdquo;志愿者服务队，成立于2019年，是在市精神文明建设指导委员会指导下，由甘愿从事社会志愿服务的民辅警、公共交通从业人员、在校学生、社会志愿者组成，现有注册志愿者713人。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">据城市公共交通分局党委书记、局长陈作雁介绍，这是一个年轻和上进的集体，自成立以来，一贯坚持&ldquo;奉献、友爱、互助、进步&rdquo;的志愿服务精神。团队不断探索、不断总结，形成了以&ldquo;侠&rdquo;文化为品牌，建设&ldquo;忠诚、仁爱、勇毅&rdquo;的平安类社会组织为目标的特色创建思路。</p>\n<div style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=1252b8a802904ae488ee77f75fce7c77\" /></div>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">随着在轨道S1线惠民路站反诈工作站的投入运行，警方将定期对志愿者开展反诈业务培训，组织志愿者进轻轨列车车厢，发放反诈宣传手册，将&ldquo;三伏茶&rdquo;改造为&ldquo;警茶&rdquo;便民服务，发挥反诈角的作用，对外公布电信诈骗典型案例，增加反诈知识有奖问答和趣味套圈等警民互动体验活动，每月组织广大市民乘客参加反诈宣传活动，有效提高公众反诈意识和能力。</p>', '社区志愿服务');
INSERT INTO `news` VALUES (39, 't001', NULL, '2024-08-07', 0, 0, '黑龙江省伊春市委启动“助力夏季旅游 青年志愿同行”主题志愿服务活动', '<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">　近日，团黑龙江省伊春市委在铁力市举行伊春市&ldquo;助力夏季旅游 青年志愿同行&rdquo;主题志愿服务活动启动仪式。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\" align=\"center\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px !important; margin: 0px 0px 15px;\" src=\"http://qnzz.youth.cn/qckc/202405/W020240521345337560757.jpeg\" alt=\"\" width=\"500\" height=\"333\" /></p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">　　仪式在青年学生代表的集体表演中拉开帷幕。团伊春市委、铁力市委及相关部门负责人向伊春市青年旅游志愿者服务队授旗，青年旅游志愿者代表宣读倡议书，号召该市青年争做志愿服务精神的传承者、践行者，助力旅游发展。启动仪式现场设置打卡助力区、旅游产品区、非遗展示区、图片展览区和急救技能宣讲区。启动仪式后，青年旅游志愿者分别深入当地特色景区开展环境卫生整治、咨询导览等志愿服务活动。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">　　活动当日，市县两级团组织共招募旅游青年志愿者622人，组建旅游青年志愿者服务队10支，并同步启动伊春市&ldquo;助力夏季旅游 青年志愿同行&rdquo;主题志愿服务活动。夏季旅游期间，青年旅游志愿者将持续深入景区、商业街区、交通枢纽等游客密集区域提供住宿、用餐、购物、乘车等咨询服务，为来伊游客提供&ldquo;一站式&rdquo;优质服务，为助力伊春夏季旅游贡献青年力量。</p>', '支教助学志愿服务');
INSERT INTO `news` VALUES (40, 't001', NULL, '2024-08-06', 0, 0, '两会声音｜全国人大代表龙翔：加快推进志愿服务立法 多举措为志愿者提供保障激励', '<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">志愿者是社会文明进步的重要力量。随着志愿服务向着组织化、专业化、社会化、信息化趋势发展，志愿服务工作体制机制建设和规范管理等方面的短板逐步凸显出来。对此，全国人大代表、南京市人大常委会主任龙翔建议，加快推进志愿服务立法，为推动全社会志愿服务事业的繁荣提供法律支持与保障。</span></p>\n<div class=\"_3hMwG _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6);\">\n<div class=\"_1NCGf\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000;\"><img style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; vertical-align: middle; border: 0px; max-width: 700px; margin: 0px auto 15px; display: block;\" src=\"https://chinavolunteer.mca.gov.cn/NVSIDF/LEAP/Download/default/news?fileid=b885185266f34807b037f43aab88b727\" /></div>\n</div>\n<div class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: center;\"><span class=\"bjh-p bjh-text-align-center\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">全国人大代表龙翔（央广网发 受访者供图）</span></div>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">近些年，志愿服务工作在推动社会文明进步、优化社会资源分配、完善基层社会治理方面发挥重要作用。&ldquo;我们在调研中发现，部分志愿服务活动也逐步暴露出一些不容忽视的问题。&rdquo;龙翔告诉记者。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">&ldquo;加快志愿服务立法是规范志愿服务活动、促进志愿队伍发展、提质志愿服务工作的迫切需要。&rdquo;龙翔建议从五个方面着手深入调研，加快推进志愿服务国家立法。具体包括以构建系统化、有序化的志愿服务工作为目标，全面优化并完善志愿服务工作体系；以专业化为导向，致力于培养符合新时代要求的高素质志愿者队伍；倡导社会化的服务理念，积极推动志愿服务的整体效能提升和质量优化；利用信息化手段，强化和完善政府部门间的协同合作与联动机制，提升志愿服务管理效率；秉持法治化原则，明晰各类志愿服务活动主体的法律责任，确保志愿服务在法治轨道上健康、有序发展。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">龙翔提出，应当重视并切实保障志愿者权益，建立健全志愿服务评价机制和激励机制，加大对志愿组织、志愿服务团队及其活动的政策支持与实质性扶持力度，完善税收支持、接受捐赠等的有关规定，完善财政资金用于志愿活动各方面支出的范围、要求等。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">此外，龙翔还建议，系统梳理志愿者开展志愿服务期间可能遭受的相关损害、伤害，细化明确各类责任归属，强化权益保障，对于恶意诋毁、侮辱志愿者的，要明确违法者担责的内容和方式。</span><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">（记者顾炀威 庄滨滨）</span></p>', '医疗救助志愿服务');
INSERT INTO `news` VALUES (41, 't001', NULL, '2024-07-02', 0, 0, '触怒我脾气扶贫', '<p>拆穿我全国肉汤工会联合颁发从</p>', '科技创新志愿服务');
INSERT INTO `news` VALUES (42, 't001', NULL, '2024-07-31', 0, 0, '2024年大学生志愿服务西部计划报名通道正式开启', '<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">教育部新闻办微信公众号&ldquo;微言教育&rdquo;发布消息，3月31日，2024年大学生志愿服务西部计划报名通道正式开启。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-size: 18px;\"><strong style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000;\">报名方式</strong></span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">即日起至5月中下旬，2024年普通高等学校应届毕业生或在读研究生，可通过微信公众号&ldquo;西部志愿汇&rdquo;（菜单栏中的&ldquo;我要报名&rdquo;）或登录西部计划官方网站，在西部计划报名系统中进行注册报名。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">据悉，大学生志愿服务西部计划（简称西部计划）是由共青团中央、教育部、财政部、人力资源社会保障部共同组织实施的一项重大人才工程。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">西部计划自2003年实施以来，已累计招募了超过50万名高校毕业生和在读研究生，到2000多个县（市、区、旗）基层服务，在全社会尤其是青年中唱响了到西部去、到基层去、到祖国和人民最需要的地方去建功立业的时代旋律。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">2024&mdash;2025年度，由中央财政支持，面向普通高等学校（教育部《全国普通高校名单》所列高校）应届毕业生或在读研究生，按照公开招募、自愿报名、组织选拔、集中派遣的方式，招募选派西部计划全国项目志愿者到西部地区基层工作（含已招募的第二十六届中国青年志愿者扶贫接力计划研究生支教团志愿者）。各地参照全国项目的运行模式和工作要求，组织实施西部计划地方项目。西部计划全国项目和地方项目均可通过西部计划官方网站报名。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-size: 18px;\"><strong style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000;\">西部计划服务内容</strong></span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">西部计划的服务内容分为乡村教育、服务乡村建设、健康乡村、基层青年工作、乡村社会治理、卫国戍边、服务新疆、服务西藏8个专项，志愿者服务期为1至3年，服务协议一年一签。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-size: 18px;\"><strong style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000;\">西部计划志愿者选拔标准</strong></span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">拥护中国共产党领导，热爱祖国、热爱人民、热爱社会主义，理想信念坚定，思想政治素质好；到岗之前获得毕业证书和学位证书；通过西部计划体检；有志愿服务经历的优先录用。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; font-size: 18px;\"><strong style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000;\">西部计划志愿者待遇和优惠政策</strong></span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); text-align: justify; line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">西部计划作为中央举办、地方受益的国家项目，所需经费由中央和地方财政共同承担。符合相关条件的西部计划志愿者可以在考研、报考公务员、计算工龄等方面享受一系列保障政策。</span></p>\n<p class=\"dpu8C _2kCxD \" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\"><span class=\"bjh-p\" style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; display: inline;\">关于报名还可咨询西部计划全国项目办、各省（区、市）西部计划项目办。</span></p>', '支教助学志愿服务');
INSERT INTO `news` VALUES (43, 't001', NULL, '2024-07-29', 0, 0, '江苏连云港：连云港启动“争当河小青 共建美丽港城”志愿服务活动', '<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">昨日，连云港市举行&ldquo;守护幸福河湖关爱美丽海湾&rdquo;&mdash;&mdash;&ldquo;争当河小青共建美丽港城&rdquo;志愿服务活动启动仪式。市委副书记卢刚出席仪式并讲话。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">活动现场为&ldquo;红领巾小河长&rdquo;中队授旗，为去年我市青年志愿者行动先进典型颁奖，为&ldquo;青年河长助理&rdquo;代表颁发聘书，随后发布了&ldquo;争当河小青共建美丽港城&rdquo;志愿服务项目，并为&ldquo;河小青&rdquo;志愿服务队授旗。</p>\n<p style=\"--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-scroll-snap-strictness: proximity; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / .5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; margin: 0px; color: #333333; text-indent: 2em; font-family: 微软雅黑; background-color: rgba(255, 255, 255, 0.6); line-height: 40px !important;\">活动要求，港城青年一代要做美丽港城的宣传者，推动&ldquo;守护幸福河湖关爱美丽海湾&rdquo;宣传活动进社区、进园区、进学校，引领身边群众关心、支持、参与幸福河湖建设，保护水资源、改善水环境，共同打造水清、岸绿、景美的良好水生态；要做美丽港城的服务者，通过志愿服务的方式参与爱河、护河、巡河，营造全社会爱河护河的浓厚气氛，凝聚起保护河湖资源的强大合力；要做美丽港城的助力者，投身基层一线，积极协助各级河长开展生态监测、源头排查、岸线整治，为美丽港城建设贡献更大青春力量。</p>', '社区志愿服务');
INSERT INTO `news` VALUES (44, 't007', NULL, '2024-07-12', 0, 1, '测试新闻', '<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\">\n<tbody>\n<tr>\n<td style=\"width: 32.9542%;\">1</td>\n<td style=\"width: 32.9542%;\">我的</td>\n<td style=\"width: 32.9578%;\">优秀</td>\n</tr>\n<tr>\n<td style=\"width: 32.9542%;\">2</td>\n<td style=\"width: 32.9542%;\">你的</td>\n<td style=\"width: 32.9578%;\">良好</td>\n</tr>\n<tr>\n<td style=\"width: 32.9542%;\">3</td>\n<td style=\"width: 32.9542%;\">他（她）的</td>\n<td style=\"width: 32.9578%;\">合格</td>\n</tr>\n</tbody>\n</table>', '环保志愿服务');
